const webhookItem = $('Webhook1').first()?.json || {};
const cfg = $input.first()?.json || {};
const rawHeaders = webhookItem.headers || {};
const headers = {};
for (const [k, v] of Object.entries(rawHeaders)) {
  headers[String(k).toLowerCase()] = String(v ?? '');
}
const body = webhookItem.body && typeof webhookItem.body === 'object' ? webhookItem.body : {};

const isAuthorizedDryRun =
  body._dry_run === true &&
  Boolean(cfg.webhookSecret) &&
  headers['x-webhook-secret'] === String(cfg.webhookSecret);

if (body.object !== 'instagram' || !Array.isArray(body.entry)) {
  return [];
}

const ownId = String(cfg.instagramAccountId || '17841466030342647').trim();
const ownUser = String(cfg.instagramUsername || 'asra3_jobs').trim().toLowerCase();

const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.processedCommentIds)) {
  staticData.processedCommentIds = [];
}
const seen = new Set(staticData.processedCommentIds);
const out = [];

for (const entry of body.entry) {
  const changes = Array.isArray(entry?.changes) ? entry.changes : [];
  for (const change of changes) {
    if (change?.field !== 'comments') continue;
    const val = change.value || {};
    const commentId = String(val.id || val.comment_id || '').trim();
    const text = String(val.text || '').trim();
    const fromId = String(val.from?.id || '').trim();
    const fromUsername = String(val.from?.username || '').trim();
    const mediaId = String(val.media?.id || '').trim();
    const parentId = String(val.parent_id || '').trim();

    if (!commentId || !text) continue;
    if ((ownId && fromId === ownId) || (ownUser && fromUsername.toLowerCase() === ownUser)) {
      continue;
    }

    if (!isAuthorizedDryRun) {
      if (seen.has(commentId)) continue;
      seen.add(commentId);
      staticData.processedCommentIds.push(commentId);
    }

    out.push({
      json: {
        platform: 'instagram',
        comment_id: commentId,
        media_id: mediaId,
        text,
        from_id: fromId,
        username: fromUsername,
        parent_id: parentId,
        own_account_id: ownId,
        own_username: ownUser,
        dry_run: isAuthorizedDryRun,
      },
    });
  }
}

if (staticData.processedCommentIds.length > 500) {
  staticData.processedCommentIds = staticData.processedCommentIds.slice(-500);
}

return out;

const extracted = $('extractIgComments').all();
const resolvedList = $input.all();
const cfg = $('configCredentials').first().json;

const hasCreds =
  Boolean(cfg.instagramAccountId) &&
  cfg.instagramAccountId !== 'YOUR_INSTAGRAM_BUSINESS_ACCOUNT_ID' &&
  Boolean(cfg.instagramAccessToken) &&
  cfg.instagramAccessToken !== 'YOUR_INSTAGRAM_ACCESS_TOKEN';

return extracted.map((srcItem, idx) => {
  const src = srcItem.json || {};
  const res = resolvedList[idx]?.json || {};
  const apiOk = res.ok === true && !res.error;
  const readyToSend =
    apiOk &&
    res.should_reply === true &&
    src.dry_run !== true &&
    Boolean(src.comment_id) &&
    Boolean(res.dm_text) &&
    hasCreds;

  return {
    json: {
      ...src,
      resolve_ok: apiOk,
      resolve_error: res.error ? String(res.error.message || res.error) : null,
      should_reply: apiOk && res.should_reply === true,
      ready_to_send: readyToSend,
      skip_reason: apiOk ? (res.skip_reason || null) : 'resolve_api_error',
      matched_rule: res.matched_rule || null,
      matched_keyword: res.matched_keyword || null,
      matched_country: res.matched_country || null,
      job_slug: res.job_slug || null,
      target_url: res.target_url || null,
      dm_text: res.dm_text || null,
      public_reply_text: res.public_reply_text || null,
      public_reply_fallback_text: res.public_reply_fallback_text || null,
      instagramAccountId: cfg.instagramAccountId,
      instagramAccessToken: cfg.instagramAccessToken,
    },
  };
});

const trueItems = $('ifShouldReply').all(0);
const dmResponses = $input.all();
const out = [];

for (let i = 0; i < trueItems.length; i++) {
  const base = trueItems[i]?.json || {};
  const dmRes = dmResponses[i]?.json || {};
  const dmSucceeded = Boolean((dmRes.message_id || dmRes.recipient_id) && !dmRes.error);
  const replyMessage = dmSucceeded
    ? String(base.public_reply_text || '')
    : String(base.public_reply_fallback_text || base.public_reply_text || '');

  if (!base.comment_id || !replyMessage) continue;

  out.push({
    json: {
      comment_id: base.comment_id,
      instagramAccessToken: base.instagramAccessToken,
      dm_succeeded: dmSucceeded,
      dm_message_id: dmRes.message_id || null,
      dm_error: dmRes.error ? String(dmRes.error.message || JSON.stringify(dmRes.error)) : null,
      reply_message: replyMessage,
    },
  });
}

return out;
